{"name":"n8n - OpenRouter Newsletter Flow.json","type":"code/json","content":"{
  "name": "Weekly Newsletter - OpenRouter",
  "nodes": [
    {
      "id": "1",
      "name": "Schedule Trigger",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1,
      "position": [100, 100],
      "parameters": {
        "rule": {
          "interval": [
            {
              "field": "cronExpression",
              "expression": "0 9 * * 1"
            }
          ]
        }
      },
      "notes": "Runs every Monday at 9 AM (edit cron if you want)")
    },
    {
      "id": "2",
      "name": "Read Google Sheets",
      "type": "n8n-nodes-base.googleSheets",
      "typeVersion": 3,
      "position": [320, 100],
      "parameters": {
        "authentication": "serviceAccount",
        "documentId": {
          "value": "https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit",
          "mode": "url"
        },
        "sheetName": {
          "value": "Subscribers",
          "mode": "name"
        },
        "options": {}
      },
      "notes": "Reads all rows from the sheet. Column headers expected: SubscriberID, Name, Email"
    },
    {
      "id": "3",
      "name": "Generate Newsletter (OpenRouter)",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 1,
      "position": [540, 100],
      "parameters": {
        "requestMethod": "POST",
        "url": "=https://openrouter.ai/api/v1/chat/completions",
        "responseFormat": "json",
        "jsonParameters": true,
        "options": {},
        "bodyParametersJson": "={\n  \"model\": \"openrouter/auto\",\n  \"messages\": [\n    {\n      \"role\": \"system\",\n      \"content\": \"You are a professional newsletter writer.\"\n    },\n    {\n      \"role\": \"user\",\n      \"content\": \"Create a newsletter about recent industry trends and tips. Include: 1. A compelling subject line 2. A greeting 3. Main content (3-4 paragraphs) 4. A call-to-action 5. A closing. Format as: SUBJECT: [subject line here] CONTENT: [full newsletter content here]\"\n    }\n  ],\n  \"max_tokens\": 500,\n  \"temperature\": 0.8\n}" 
      },
      "notes": "Sends a single prompt to OpenRouter to generate the newsletter. Use credentials or add header Authorization: Bearer YOUR_KEY in node credentials."
    },
    {
      "id": "4",
      "name": "Process Data",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [760, 100],
      "parameters": {
        "jsCode": "// Extract subject and content from OpenRouter response\nconst aiResponse = $input.first().json.choices[0].message.content || $input.first().json.choices[0].text || '';\n\nconst subjectMatch = aiResponse.match(/SUBJECT:\\s*(.+?)\\n/);\nconst contentMatch = aiResponse.match(/CONTENT:\\s*([\\s\\S]+)/);\n\nconst subject = subjectMatch ? subjectMatch[1].trim() : 'Weekly Newsletter';\nconst content = contentMatch ? contentMatch[1].trim() : aiResponse;\n\n// Get all subscribers from Google Sheets node\nconst subscribers = $('Read Google Sheets').all();\n\nreturn subscribers.map(subscriber => ({\n  json: {\n    email: subscriber.json.Email || subscriber.json.email,\n    name: subscriber.json.Name || subscriber.json.name || '',\n    subject: subject,\n    content: content,\n    subscriberId: subscriber.json.SubscriberID || subscriber.json.SubscriberId || ''\n  }\n}));"
      },
      "notes": "Parses AI output and creates one output item per subscriber (no extra AI calls)."
    },
    {
      "id": "5",
      "name": "Send Email",
      "type": "n8n-nodes-base.emailSend",
      "typeVersion": 2,
      "position": [980, 100],
      "parameters": {
        "fromEmail": "newsletter@yourdomain.com",
        "toEmail": "={{ $json.email }}",
        "subject": "={{ $json.subject }}",
        "text": "={{ $json.content }}",
        "options": {}
      },
      "notes": "Configure SMTP credentials in n8n Credentials and update From address."
    },
    {
      "id": "6",
      "name": "Log Sent Emails",
      "type": "n8n-nodes-base.googleSheets",
      "typeVersion": 3,
      "position": [1200, 100],
      "parameters": {
        "operation": "append",
        "documentId": {
          "value": "https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit",
          "mode": "url"
        },
        "sheetName": {
          "value": "Sent Log",
          "mode": "name"
        },
        "options": {
          "dataPropertyName": "data"
        }
      },
      "notes": "Appends a row for every sent email. Configure columns in sheet (Timestamp, SubscriberID, Email, Subject)."
    }
  ],
  "connections": {
    "Schedule Trigger": { "main": [[ { "node": "Read Google Sheets", "type": "main", "index": 0 } ]] },
    "Read Google Sheets": { "main": [[ { "node": "Generate Newsletter (OpenRouter)", "type": "main", "index": 0 } ]] },
    "Generate Newsletter (OpenRouter)": { "main": [[ { "node": "Process Data", "type": "main", "index": 0 } ]] },
    "Process Data": { "main": [[ { "node": "Send Email", "type": "main", "index": 0 } ]] },
    "Send Email": { "main": [[ { "node": "Log Sent Emails", "type": "main", "index": 0 } ]] }
  },
  "active": false,
  "settings": {}
}
"}

